import sys

uopcodes = set()

for file in sys.argv[1:]:
    uopcodes.update([uc.strip() for uc in open(file).readlines()])

sorted_uopcodes = sorted(uopcodes)

with open("uopcodes.h", "w") as uopcodes_out:
    enum_names = ",\n    ".join(sorted_uopcodes)
    print(
        f"""
// Copyright (c) 2021-2024, Ampere Computing LLC
// SPDX-License-Identifier: BSD-3-Clause
//
// Generated by build_uopcodes.py. DO NOT EDIT!
//
#pragma once

#include <ostream>
#include <string>

#include <fmt/core.h>
#include <fmt/ostream.h>

namespace ampere::archx {{

enum class Uopcode {{
    INVALID,
    {enum_names}
}};

std::string uopcode_to_string(Uopcode uopcode);
std::ostream& operator<<(std::ostream& os, Uopcode);

}} // namespace ampere::archx

template<>
struct fmt::formatter<ampere::archx::Uopcode> : fmt::ostream_formatter {{}};
    """,
        file=uopcodes_out,
    )

with open("uopcodes.cc", "w") as uopcodes_out:
    strings = ",\n        ".join([f'"{u.lower()}"' for u in sorted_uopcodes])
    print(
        f"""
// Copyright (c) 2021-2024, Ampere Computing LLC
// SPDX-License-Identifier: BSD-3-Clause
//
// Generated by build_uopcodes.py. DO NOT EDIT!
//
#include "uopcodes.h"

namespace ampere::archx {{

std::string uopcode_to_string(Uopcode uopcode) {{
    static const char* names[] = {{
        "invalid",
        {strings}
    }};
    return names[static_cast<int>(uopcode)];
}}

std::ostream& operator<<(std::ostream& os, Uopcode uopcode) {{
    os << uopcode_to_string(uopcode);
    return os;
}}

}} // namespace ampere::archx
""",
        file=uopcodes_out,
    )
